import { Controller, Get, Post, Put, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 승인 완료 상태는 '승인'과 '완료' 두 가지로 본다.
const APPROVED_STATUSES = ['승인', '완료'];

const amountError = (message: string) =>
  new ApiError(422, 'ASSET_ITEM_AMOUNT_EXCEEDED', message);

function isId(value: unknown): boolean {
  return /^\d+$/.test(String(value ?? ''));
}

function readItem(data: Record<string, unknown>) {
  const itemName = typeof data.itemName === 'string' ? data.itemName.trim() : '';
  if (itemName === '' || itemName.length > 200) {
    throw amountError('품목명을 확인해 주세요.');
  }
  const quantity = data.quantity;
  if (typeof quantity !== 'number' || !Number.isInteger(quantity) || quantity <= 0) {
    throw amountError('수량은 1 이상의 정수여야 합니다.');
  }
  const unitPrice = data.unitPrice;
  if (typeof unitPrice !== 'number' || !Number.isFinite(unitPrice) || unitPrice < 0) {
    throw amountError('단가는 0 이상의 숫자여야 합니다.');
  }
  return { itemName, quantity, unitPrice };
}

@Controller('api/v1')
export class FnSfr02404Controller {
  @Get('/purchase-asset-items')
  async listPurchaseAssetItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const query = checks.queryOf(req.query);
    if (!isId(query.purchaseRequestId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의서를 선택해 주세요.');
    }
    const page = Math.max(0, parseInt(String(query.page ?? '0'), 10) || 0);
    let size = parseInt(String(query.size ?? '20'), 10) || 20;
    size = Math.min(Math.max(size, 1), 200);
    return transaction(async (db) => {
      const params = {
        purchaseRequestId: String(query.purchaseRequestId),
        limit: size,
        offset: page * size,
      };
      const rows = await db.query(
        'SELECT i.purchase_asset_item_id AS "purchaseAssetItemId", i.item_name AS "itemName", ' +
          'i.quantity AS "quantity", i.unit_price AS "unitPrice", i.amount AS "amount", ' +
          'r.asset_inspection_required AS "assetInspectionRequired" ' +
          'FROM purchase_asset_item i ' +
          'JOIN purchase_request r ON r.purchase_request_id = i.purchase_request_id ' +
          'WHERE i.purchase_request_id = CAST(:purchaseRequestId AS bigint) ' +
          'ORDER BY i.purchase_asset_item_id ' +
          'LIMIT :limit OFFSET :offset',
        params,
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM purchase_asset_item ' +
          'WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)',
        { purchaseRequestId: params.purchaseRequestId },
      );
      return { items: rows, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/purchase-asset-items')
  @HttpCode(200)
  async createPurchaseAssetItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const data = checks.inputOf(req.body);
    if (!isId(data.purchaseRequestId)) {
      throw amountError('품의서를 선택해 주세요.');
    }
    const item = readItem(data);
    return transaction(async (db) => {
      const requests = await db.query(
        'SELECT amount AS "amount", approval_status AS "approvalStatus" FROM purchase_request ' +
          'WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint) FOR UPDATE',
        { purchaseRequestId: String(data.purchaseRequestId) },
      );
      if (requests.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      if (APPROVED_STATUSES.includes(requests[0].approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_APPROVED', '승인 완료된 품의서의 자산품목은 등록할 수 없습니다.');
      }
      const calc = await db.query(
        'SELECT CAST(:quantity AS integer) * CAST(:unitPrice AS numeric) AS "amount"',
        { quantity: item.quantity, unitPrice: item.unitPrice },
      );
      const sums = await db.query(
        'SELECT COALESCE(SUM(amount), 0) AS "sum" FROM purchase_asset_item ' +
          'WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)',
        { purchaseRequestId: String(data.purchaseRequestId) },
      );
      if (Number(sums[0].sum) + Number(calc[0].amount) > Number(requests[0].amount)) {
        throw amountError('자산품목 금액 합계가 품의 금액을 초과할 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO purchase_asset_item ' +
          '(purchase_request_id, item_name, quantity, unit_price, amount, created_at, updated_at) ' +
          'VALUES (CAST(:purchaseRequestId AS bigint), :itemName, :quantity, CAST(:unitPrice AS numeric), ' +
          'CAST(:quantity AS integer) * CAST(:unitPrice AS numeric), now(), now()) ' +
          'RETURNING purchase_asset_item_id AS "purchaseAssetItemId", amount AS "amount"',
        {
          purchaseRequestId: String(data.purchaseRequestId),
          itemName: item.itemName,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
        },
      );
      return rows[0];
    });
  }

  @Put('/purchase-asset-items/:purchaseAssetItemId')
  async updatePurchaseAssetItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const data = checks.inputOf(req.body);
    const itemId = req.params['purchaseAssetItemId'];
    const item = readItem(data);
    return transaction(async (db) => {
      if (!isId(itemId)) {
        throw new ApiError(404, 'PURCHASE_ASSET_ITEM_NOT_FOUND', '자산품목을 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT i.purchase_request_id AS "purchaseRequestId", r.amount AS "requestAmount", ' +
          'r.approval_status AS "approvalStatus" ' +
          'FROM purchase_asset_item i ' +
          'JOIN purchase_request r ON r.purchase_request_id = i.purchase_request_id ' +
          'WHERE i.purchase_asset_item_id = CAST(:itemId AS bigint) FOR UPDATE OF r',
        { itemId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_ASSET_ITEM_NOT_FOUND', '자산품목을 찾을 수 없습니다.');
      }
      if (APPROVED_STATUSES.includes(found[0].approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_APPROVED', '승인 완료된 품의서의 자산품목은 수정할 수 없습니다.');
      }
      const calc = await db.query(
        'SELECT CAST(:quantity AS integer) * CAST(:unitPrice AS numeric) AS "amount"',
        { quantity: item.quantity, unitPrice: item.unitPrice },
      );
      const sums = await db.query(
        'SELECT COALESCE(SUM(amount), 0) AS "sum" FROM purchase_asset_item ' +
          'WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint) ' +
          'AND purchase_asset_item_id <> CAST(:itemId AS bigint)',
        { purchaseRequestId: String(found[0].purchaseRequestId), itemId },
      );
      if (Number(sums[0].sum) + Number(calc[0].amount) > Number(found[0].requestAmount)) {
        throw amountError('자산품목 금액 합계가 품의 금액을 초과할 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE purchase_asset_item SET item_name = :itemName, quantity = :quantity, ' +
          'unit_price = CAST(:unitPrice AS numeric), ' +
          'amount = CAST(:quantity AS integer) * CAST(:unitPrice AS numeric), updated_at = now() ' +
          'WHERE purchase_asset_item_id = CAST(:itemId AS bigint) ' +
          'RETURNING purchase_asset_item_id AS "purchaseAssetItemId", amount AS "amount"',
        { itemId, itemName: item.itemName, quantity: item.quantity, unitPrice: item.unitPrice },
      );
      return rows[0];
    });
  }

  @Patch('/purchase-requests/:purchaseRequestId/asset-inspection')
  async setPurchaseRequestAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const data = checks.inputOf(req.body);
    const requestId = req.params['purchaseRequestId'];
    if (typeof data.assetInspectionRequired !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산 검수 여부를 선택해 주세요.');
    }
    return transaction(async (db) => {
      if (!isId(requestId)) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM purchase_request ' +
          'WHERE purchase_request_id = CAST(:requestId AS bigint) FOR UPDATE',
        { requestId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      if (APPROVED_STATUSES.includes(found[0].approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_APPROVED', '승인 완료된 품의서의 검수 여부는 설정할 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE purchase_request SET asset_inspection_required = :required, updated_at = now() ' +
          'WHERE purchase_request_id = CAST(:requestId AS bigint) ' +
          'RETURNING purchase_request_id AS "purchaseRequestId", ' +
          'asset_inspection_required AS "assetInspectionRequired"',
        { requestId, required: data.assetInspectionRequired },
      );
      return rows[0];
    });
  }
}

