import { useState } from 'react';
import {
  call, useData, Badge, Num, Filters, Band, DataTable, Pager, Drawer, Tiles,
  Form, Field, TextInput, NumberInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode = { type: 'create' } | { type: 'edit'; row: Row } | { type: 'inspect' } | null;

function ItemForm({ role, requestId, row, onDone }: { role: string; requestId: number | string; row?: Row; onDone: () => void }) {
  const [itemName, setItemName] = useState<unknown>(row ? row.itemName : '');
  const [quantity, setQuantity] = useState<unknown>(row ? row.quantity : '');
  const [unitPrice, setUnitPrice] = useState<unknown>(row ? row.unitPrice : '');
  return (
    <Form
      submit={row ? '수정' : '등록'}
      onSubmit={async () => {
        if (String(itemName).trim() === '' || quantity === '' || unitPrice === '') {
          throw new Error('품목명, 수량, 단가를 모두 입력해 주세요.');
        }
        const body: Row = { itemName, quantity, unitPrice };
        if (row) {
          await call('PUT', '/purchase-asset-items/' + row.purchaseAssetItemId, role, body);
        } else {
          await call('POST', '/purchase-asset-items', role, { ...body, purchaseRequestId: requestId });
        }
        onDone();
      }}
    >
      <Field label="품목명" required wide>
        <TextInput value={itemName} onChange={setItemName} />
      </Field>
      <Field label="수량" required>
        <NumberInput value={quantity} onChange={setQuantity} />
      </Field>
      <Field label="단가" required>
        <NumberInput value={unitPrice} onChange={setUnitPrice} />
      </Field>
    </Form>
  );
}

function InspectForm({ role, requestId, current, onDone }: { role: string; requestId: number | string; current: boolean; onDone: () => void }) {
  const [value, setValue] = useState<string>(current ? 'true' : 'false');
  return (
    <Form
      submit="설정"
      onSubmit={async () => {
        await call('PATCH', '/purchase-requests/' + requestId + '/asset-inspection', role, {
          assetInspectionRequired: value === 'true',
        });
        onDone();
      }}
    >
      <Field label="자산 검수 여부" required>
        <Select
          value={value}
          onChange={setValue}
          options={[['true', '검수 필요'], ['false', '검수 불필요']]}
          placeholder="선택"
        />
      </Field>
    </Form>
  );
}

export default function FnSfr02404Page({ role, notify }: PageProps) {
  const [draftId, setDraftId] = useState<number | string>('');
  const [requestId, setRequestId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const [error, setError] = useState('');
  const size = 20;

  const { data, error: loadError, reload } = useData<Page>(async () => {
    if (requestId === '') {
      return { items: [], page: 0, size, total: 0 };
    }
    return call<Page>('GET', '/purchase-asset-items', role, undefined, { purchaseRequestId: requestId, page, size });
  }, [requestId, page, role]);

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const amountSum = items.reduce((sum, r) => sum + Number(r.amount || 0), 0);
  const inspection = items.length > 0 ? Boolean(items[0].assetInspectionRequired) : false;

  function search() {
    if (draftId === '') {
      setError('품의서를 선택해 주세요.');
      return;
    }
    setError('');
    setPage(0);
    setRequestId(draftId);
  }

  function done(text: string) {
    setMode(null);
    notify(text);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>자산품목 요약</h2>
        <Tiles
          items={[
            ['자산품목 수', <Num value={total} />],
            ['금액 합계', <Num value={amountSum} />],
            ['자산 검수 여부', requestId === '' ? '-' : <Badge value={inspection ? '검수 필요' : '검수 불필요'} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>자산품목</h2>
        <Filters
          onSearch={search}
          onReset={() => {
            setDraftId('');
            setRequestId('');
            setPage(0);
            setError('');
          }}
        >
          <Field label="품의서" required>
            <LookupSelect table="purchase_request" role={role} value={draftId} onChange={setDraftId} placeholder="품의서 선택" />
          </Field>
        </Filters>
        {error !== '' && <ErrorText text={error} />}
        {loadError !== '' && <ErrorText text={loadError} />}
        <Band total={total}>
          <button type="button" disabled={requestId === ''} onClick={() => setMode({ type: 'create' })}>
            자산품목 등록
          </button>
          <button type="button" disabled={requestId === ''} onClick={() => setMode({ type: 'inspect' })}>
            검수 여부 설정
          </button>
        </Band>
        <DataTable
          rows={items}
          empty={requestId === '' ? '품의서를 선택하고 조회해 주세요.' : '등록된 자산품목이 없습니다.'}
          columns={[
            { key: 'itemName', label: '품목명' },
            { key: 'quantity', label: '수량', render: (r) => <Num value={r.quantity} /> },
            { key: 'unitPrice', label: '단가', render: (r) => <Num value={r.unitPrice} /> },
            { key: 'amount', label: '금액', render: (r) => <Num value={r.amount} /> },
            {
              key: 'assetInspectionRequired',
              label: '자산 검수 여부',
              render: (r) => <Badge value={r.assetInspectionRequired ? '검수 필요' : '검수 불필요'} />,
            },
            {
              key: 'purchaseAssetItemId',
              label: '처리',
              render: (r) => (
                <button type="button" onClick={() => setMode({ type: 'edit', row: r })}>
                  수정
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={size} total={total} onPage={setPage} />
        {requestId !== '' && (
          <p>
            선택한 품의서: <RefName table="purchase_request" role={role} value={requestId} />
          </p>
        )}
      </section>
      {mode && mode.type === 'create' && (
        <Drawer title="자산품목 등록" onClose={() => setMode(null)}>
          <ItemForm role={role} requestId={requestId} onDone={() => done('자산품목을 등록했습니다.')} />
        </Drawer>
      )}
      {mode && mode.type === 'edit' && (
        <Drawer title="자산품목 수정" onClose={() => setMode(null)}>
          <ItemForm role={role} requestId={requestId} row={mode.row} onDone={() => done('자산품목을 수정했습니다.')} />
        </Drawer>
      )}
      {mode && mode.type === 'inspect' && (
        <Drawer title="자산 검수 여부 설정" onClose={() => setMode(null)}>
          <InspectForm role={role} requestId={requestId} current={inspection} onDone={() => done('자산 검수 여부를 설정했습니다.')} />
        </Drawer>
      )}
    </div>
  );
}
